// Extract classification from Gemini response and determine target folder
const items = $input.all();
const results = [];

for (const item of items) {
  const geminiResponse = item.json.candidates[0].content.parts[0].text.trim();

  // Map classification to folder
  let targetFolder = 'CouldNotClassify';

  if (geminiResponse.toLowerCase().includes('invoice')) {
    targetFolder = 'Invoices';
  } else if (geminiResponse.toLowerCase().includes('bank statement')) {
    targetFolder = 'BankStatements';
  } else if (geminiResponse.toLowerCase().includes('tax record')) {
    targetFolder = 'TaxRecords';
  } else if (geminiResponse.toLowerCase().includes('executive report')) {
    targetFolder = 'ExecutiveReports';
  }

  // Get source file path from earlier node
  const sourceFilePath = item.json.filePath;
  const fileName = item.json.fileName;

  // Construct target path using absolute paths
  const basePath = $node['Set Processing Paths'].json.targetBasePath;
  const targetPath = `${basePath}/Processed/${targetFolder}/${fileName}`;

  results.push({
    json: {
      fileName: fileName,
      sourceFilePath: sourceFilePath,
      targetPath: targetPath,
      classification: geminiResponse,
      targetFolder: targetFolder,
      processedAt: new Date().toISOString()
    }
  });
}

return results;
